    OClass schema = ODocumentInternal.getImmutableSchemaClass(((ODocument) doc));
    if (schema == null) return className == null;
    else if (schema.getName().equals(className)) {
      return true;
    } else if (schema.isSubClassOf(className)) {
      return true;
    }
    return false;
  }

