private static String baseDNOuScope(String baseDN) {
    List<String> ouScopes = new ArrayList<>();
    String[] rdnList = baseDN.toLowerCase().split(",");
    for (String s : rdnList) {
        if (s.startsWith("ou=")) {
            ouScopes.add(s);
        }
    }
    return String.join(",", ouScopes);
}

