    return;
}
// 计算超时时间
int alarmTime = cache.alarmTime();
long timeout;
if (alarmTime > 0 && alarmTime < expire) {
    timeout = expire - alarmTime;
} else {
    if (expire >= 600) {
        timeout = expire - REFRESH_MIN_EXPIRE;
    } else {
        timeout = expire - 60;
    }
}

if ((System.currentTimeMillis() - cacheWrapper.getLastLoadTime()) < (timeout * ONE_THOUSAND_MS)) {
    return;
