public void call(ClientSide clientSide, String data) {

	Room room = ServerContains.getRoom(clientSide.getRoomId());
	Map<String, Object> map = MapHelper.parser(data);
	int highestScore = (Integer)map.get("highestScore");

	if (room == null) {
		return;
	}
	if (highestScore == 3) {
		room.setBaseScore(highestScore);
		confirmLandlord(clientSide, room);
		return;
	}
	if (clientSide.getNext().getId() == room.getFirstSellClient()) {
		if (highestScore == 0) {
			for (ClientSide client : room.getClientSideList()) {
				if (client.getRole() == ClientRole.PLAYER) {
					ChannelUtils.pushToClient(client.getChannel(), ClientEventCode.CODE_GAME_LANDLORD_CYCLE, null);
				}

					allReady = false;
					break;
				}
			}
		}

		for (ClientSide client : room.getClientSideList()) {
			if (client.getRole() == ClientRole.PLAYER) {
				ChannelUtils.pushToClient(client.getChannel(), ClientEventCode.CODE_GAME_READY, result);
			}
		}

		if (allReady) {
			ServerEventListener.get(ServerEventCode.CODE_GAME_STARTING).call(clientSide, data);
		}
	}
}

