 * 通知观战者游戏结束
 *
 * @param room	房间
 * @param result	出牌信息
 */
private void notifyWatcherGameOver(Room room, String  result) {
	for (ClientSide watcher : room.getWatcherList()) {
		ChannelUtils.pushToClient(watcher.getChannel(), ClientEventCode.CODE_GAME_OVER, result);
	}
}

	notifyWatcherGameStart(room);
}


/**
 * 通知房间内的观战人员游戏开始
 *
 * @param room	房间
 */
private void notifyWatcherGameStart(Room room) {
	String result = MapHelper.newInstance()
			.put("player1", room.getClientSideList().getFirst().getNickname())
			.put("player2", room.getClientSideList().getFirst().getNext().getNickname())
			.put("player3", room.getClientSideList().getLast().getNickname())
			.json();
	for (ClientSide clientSide : room.getWatcherList()) {
		ChannelUtils.pushToClient(clientSide.getChannel(), ClientEventCode.CODE_GAME_STARTING, result);
	}
}

		if (client.getType() == ClientType.LANDLORD && client.getRound() > 1) {
			isSpring = false;
		}
	}
	return isSpring;
}

/**
 * 通知观战者出牌信息
 *
 * @param room	房间
 * @param result	出牌信息
 */
private void notifyWatcherPlayPoker(Room room, String result) {
	for (ClientSide watcher : room.getWatcherList()) {
		ChannelUtils.pushToClient(watcher.getChannel(), ClientEventCode.CODE_SHOW_POKERS, result);
	}
}

